#include <iostream>

int main() {
    int fichas = 14;
    int capacidad = 4;
    int codigo_sobrantes = 1;

    const bool acepta_sobrantes = codigo_sobrantes != 0;

    if ((fichas < 0) || (fichas > 30) || (capacidad < 1) || (capacidad > 6)) {
        std::cout << "Datos invalidos";
    } else if (fichas == 0) {
        std::cout << "Sin trabajo";
    } else {
        const int grupos = fichas / capacidad;
        const int sobrantes = fichas % capacidad;

        if (sobrantes != 0 && !acepta_sobrantes) {
            std::cout << "Reparto pendiente";
        } else {
            std::cout << "Grupos: " << grupos;

            if (sobrantes != 0) {
                std::cout << "\nSobrantes: " << sobrantes;
            }
        }
    }

    return 0;
}

